0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"Blog – WordPress.org tiếng Việt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://vi.wordpress.org\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"width\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"height\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:63:\"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"Online WordPress Meetup Hanoi – 08/09/2025\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:67:\"https://vi.wordpress.org/2025/09/04/wordpress-meetup-hanoi-09-2025/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 04 Sep 2025 03:08:03 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:3:{i:0;a:5:{s:4:\"data\";s:6:\"Meetup\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:9:\"Tin tức\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:22:\"Hanoi WordPress Meetup\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://vi.wordpress.org/?p=1270\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:380:\"Thật tuyệt vời vì những người yêu mến WordPress lại có thể chia sẻ về cách sử dụng WordPress tại Hà Nội vào ngày 08/09/2025, qua hình thức online. Thời gian 18:00 &#8211; 20:00 ngày 08/09/2025 Địa điểm: Online, đăng ký trước qua Meetup.com Nội dung chương trình Phần 1: Networking (Giới thiệu &#8211; Làm [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Khoi Pro\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2365:\"\n<p class=\"wp-block-paragraph\">Thật tuyệt vời vì những người yêu mến WordPress lại có thể chia sẻ về cách sử dụng WordPress tại Hà Nội vào ngày 08/09/2025, qua hình thức online.</p>\n\n\n\n<span id=\"more-1270\"></span>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><a href=\"https://vi.wordpress.org/files/2024/09/z5848772322058_c3935a9f34225437d980965a05d19018.jpg\"><img fetchpriority=\"high\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://vi.wordpress.org/files/2024/09/z5848772322058_c3935a9f34225437d980965a05d19018-1024x576.jpg\" alt=\"Ảnh Meetup Hà Nội\" class=\"wp-image-1273\" srcset=\"https://vi.wordpress.org/files/2024/09/z5848772322058_c3935a9f34225437d980965a05d19018-1024x576.jpg 1024w, https://vi.wordpress.org/files/2024/09/z5848772322058_c3935a9f34225437d980965a05d19018-300x169.jpg 300w, https://vi.wordpress.org/files/2024/09/z5848772322058_c3935a9f34225437d980965a05d19018-768x432.jpg 768w, https://vi.wordpress.org/files/2024/09/z5848772322058_c3935a9f34225437d980965a05d19018.jpg 1080w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></a><figcaption class=\"wp-element-caption\">Một sự kiện đã diễn ra</figcaption></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Thời gian</h2>\n\n\n\n<p class=\"wp-block-paragraph\">18:00 &#8211; 20:00 ngày 08/09/2025</p>\n\n\n\n<h2 class=\"wp-block-heading\">Địa điểm:</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Online, đăng ký trước qua Meetup.com</p>\n\n\n\n<h2 class=\"wp-block-heading\">Nội dung chương trình</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Phần 1: Networking (Giới thiệu &#8211; Làm quen)<br>Phần 2: Bảo mật website WordPress &#8211; Speaker: Mr. Khôi (Founder <a href=\"https://codetot.vn/ve-code-tot/\">Code Tốt</a>)<br>Phần 3: Hỏi-Đáp &amp; Networking</p>\n\n\n\n<h2 class=\"wp-block-heading\">Đăng ký tham dự</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Để chuẩn bị cho sự kiện tốt nhất, vui lòng đăng ký tham gia tại trang Meetup chính thức để nhận thông báo khi sự kiện diễn ra.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://www.meetup.com/hanoi-wordpress-meetup/events/310741637/\" target=\"_blank\" rel=\"noreferrer noopener\">Đăng ký tham dự</a></div>\n</div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"1270\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:85:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"Recap sự kiện Nha Trang WordPress Meetup 2025\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://vi.wordpress.org/2025/06/22/recap-su-kien-nha-trang-wordpress-meetup-2025/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"https://vi.wordpress.org/2025/06/22/recap-su-kien-nha-trang-wordpress-meetup-2025/#comments\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 22 Jun 2025 09:20:16 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:5:{i:0;a:5:{s:4:\"data\";s:6:\"Meetup\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:11:\"Sự kiện\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:9:\"Nha Trang\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:19:\"nha trang wordpress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:26:\"Nha Trang WordPress Meetup\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://vi.wordpress.org/?p=1313\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:376:\"Sáng ngày 22/06/2025, cộng đồng Nha Trang WordPress đã tổ chức thành công sự kiện Meetup tại Stockholm Co-working Space, quy tụ gần 30 thành viên là các lập trình viên, marketer, chủ doanh nghiệp, blogger và những người yêu thích WordPress. Đây là sự kiện được mong chờ nhất năm của cộng đồng, nơi [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:25:\"Nguyễn Xuân Bình Minh\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:38793:\"\n<p class=\"wp-block-paragraph\">Sáng ngày 22/06/2025, cộng đồng Nha Trang WordPress đã tổ chức thành công sự kiện Meetup tại Stockholm Co-working Space, quy tụ gần 30 thành viên là các lập trình viên, marketer, chủ doanh nghiệp, blogger và những người yêu thích WordPress. Đây là sự kiện được mong chờ nhất năm của cộng đồng, nơi mọi người có thể cùng nhau học hỏi, thảo luận và mở rộng quan hệ trong lĩnh vực phát triển website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Bối cảnh năm 2025 chứng kiến sự phát triển vượt bậc của WordPress, khi nền tảng này chiếm gần một nửa số lượng website toàn cầu và áp đảo các đối thủ trong mảng CMS. Điều này càng củng cố vị thế của WordPress trong mắt cộng đồng công nghệ tại Việt Nam nói chung và Nha Trang nói riêng.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chương trình Meetup năm nay được đầu tư kỹ lưỡng với ba chủ đề nổi bật:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Tối ưu Facebook Funnel – Dẫn lối người dùng về website WordPress</strong><br>Diễn giả Nguyễn Phú Quý đã phân tích chi tiết các bước xây dựng phễu chuyển đổi trên Facebook, từ việc thu hút khách hàng tiềm năng đến việc đưa họ về website WordPress để tăng tỷ lệ chuyển đổi và doanh thu.</li>\n\n\n\n<li><strong>Tự động hóa sáng tạo nội dung cho website WordPress với AI và N8N</strong><br>Diễn giả Nguyễn Minh Phụng chia sẻ cách ứng dụng trí tuệ nhân tạo và công cụ N8N để tự động hóa quy trình tạo nội dung, giúp quản trị viên website tiết kiệm thời gian mà vẫn đảm bảo chất lượng và sự đa dạng của nội dung.</li>\n\n\n\n<li><strong>Xây dựng website bán sản phẩm số &amp; Tối ưu tốc độ website WordPress trên 90 điểm Google PageSpeed Insights</strong><br>Diễn giả Nguyễn Xuân Bình Minh mang đến những kinh nghiệm thực tế trong việc xây dựng hệ thống bán hàng số chuyên nghiệp, đồng thời hướng dẫn các kỹ thuật tối ưu tốc độ website, nâng cao trải nghiệm người dùng và hỗ trợ SEO hiệu quả.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Sự kiện diễn ra trong không khí thân thiện, cởi mở, với nhiều phần giao lưu, hỏi đáp trực tiếp giữa các diễn giả và người tham dự. <br><br>Xin trân trọng cám ơn các nhà tài trợ đã góp phần tạo nên một sự kiện chuyên nghiệp, đầy đủ tiện ích và hoàn toàn miễn phí cho cộng đồng.<br><strong>Đơn vị tài trợ cho sự kiện:</strong><br>&#8211; <strong>Pay5s</strong> &#8211; Giải pháp thanh toán nhanh chóng, tiện lợi (<a href=\"https://pay5s.vn/\">https://pay5s.vn/</a>)<br>&#8211; <strong>YayCommerce</strong> &#8211; Awesome WooCommerce plugins (<a href=\"https://yaycommerce.com\">https://yaycommerce.com</a>)<br>&#8211; <strong>Tino Group</strong> &#8211; Nhà đăng ký tên miền quốc gia Việt Nam, là đơn vị cho thuê, cung cấp tên miền, hosting, dịch vụ máy chủ với giá thành phải chăng (<a href=\"https://tino.vn\">https://tino.vn</a>)<br>&#8211; <strong>HITECHCLOUD</strong> &#8211; Chuyên ung cấp các dịch vụ DataCenter, người chăm sóc hệ thống hạ tầng CNTT của bạn. (<a href=\"https://hitechcloud.vn\">https://hitechcloud.vn</a>)<br>&#8211; <strong>BNIX</strong> &#8211; Nhà cung cấp Hosting/VPS/Server Chuyên Nghiệp ( <a href=\"https://bnix.vn/\">https://bnix.vn/</a> )</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Đơn vị tài trợ tổ chức: </strong>Minh Duy Solutions &#8211; Marketing Agency tại Nha Trang (<a href=\"https://minhduy.vn\">https://minhduy.vn</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Nha Trang WordPress Meetup không chỉ là nơi cập nhật kiến thức mới mà còn là môi trường lý tưởng để các thành viên chia sẻ khó khăn, kinh nghiệm thực tế và cùng nhau xây dựng một cộng đồng WordPress phát triển bền vững, đúng với tinh thần phi lợi nhuận, minh bạch và sáng tạo mà WordPress.Org đề cao.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Với sự thành công của sự kiện lần này, Nha Trang WordPress Meetup tiếp tục khẳng định vai trò là điểm hẹn uy tín của cộng đồng công nghệ địa phương, góp phần lan tỏa giá trị của mã nguồn mở và thúc đẩy sự phát triển của lĩnh vực quản lý nội dung số tại Việt Nam.<br><br>Dưới đây là một số hình ảnh của sự kiện Nha Trang WordPress Meetup 2025</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-4 is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-full\"><a href=\"https://vi.wordpress.org/files/2025/06/NTWP-2025-34.jpg\" target=\"_blank\"><img decoding=\"async\" width=\"1400\" height=\"788\" data-id=\"1349\" src=\"https://vi.wordpress.org/files/2025/06/NTWP-2025-34.jpg\" alt=\"\" class=\"wp-image-1349\" srcset=\"https://vi.wordpress.org/files/2025/06/NTWP-2025-34.jpg 1400w, https://vi.wordpress.org/files/2025/06/NTWP-2025-34-300x169.jpg 300w, https://vi.wordpress.org/files/2025/06/NTWP-2025-34-1024x576.jpg 1024w, https://vi.wordpress.org/files/2025/06/NTWP-2025-34-768x432.jpg 768w\" sizes=\"(max-width: 1400px) 100vw, 1400px\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://vi.wordpress.org/files/2025/06/NTWP-2025-35.jpg\" target=\"_blank\"><img decoding=\"async\" width=\"1400\" height=\"788\" data-id=\"1354\" src=\"https://vi.wordpress.org/files/2025/06/NTWP-2025-35.jpg\" alt=\"\" class=\"wp-image-1354\" srcset=\"https://vi.