{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:12:\"Recap Meetup\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://vi.wordpress.org/?p=1078\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:341:\"Cảm ơn anh chị em đã tham dự WordPress Meetup tại Hà Nội tháng 07/2023. Đã tròn một năm mới thấy sự quay trở lại của Meetup, và sự nhiệt thành, cùng nhau đóng góp, trao đổi đã khơi dậy rất nhiều năng lượng cho mỗi người. Trong buổi hôm nay, đại diện từ Code [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Khoi Pro\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:6073:\"\n<figure class=\"wp-block-image size-large\"><a href=\"https://vi.wordpress.org/files/2023/07/image-2.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"767\" src=\"https://vi.wordpress.org/files/2023/07/image-2-1024x767.png\" alt=\"WordPress Meetup Hà Nội tháng 07/2023\" class=\"wp-image-1081\" srcset=\"https://vi.wordpress.org/files/2023/07/image-2-1024x767.png 1024w, https://vi.wordpress.org/files/2023/07/image-2-300x225.png 300w, https://vi.wordpress.org/files/2023/07/image-2-768x575.png 768w, https://vi.wordpress.org/files/2023/07/image-2-440x330.png 440w, https://vi.wordpress.org/files/2023/07/image-2.png 1276w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Cảm ơn anh chị em đã tham dự WordPress Meetup tại Hà Nội tháng 07/2023. Đã tròn một năm mới thấy sự quay trở lại của Meetup, và sự nhiệt thành, cùng nhau đóng góp, trao đổi đã khơi dậy rất nhiều năng lượng cho mỗi người.</p>\n\n\n\n<span id=\"more-1078\"></span>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://vi.wordpress.org/files/2023/07/image.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"569\" src=\"https://vi.wordpress.org/files/2023/07/image-1024x569.png\" alt=\"Tối ưu Web mới nhất từ Code Tốt\" class=\"wp-image-1079\" srcset=\"https://vi.wordpress.org/files/2023/07/image-1024x569.png 1024w, https://vi.wordpress.org/files/2023/07/image-300x167.png 300w, https://vi.wordpress.org/files/2023/07/image-768x427.png 768w, https://vi.wordpress.org/files/2023/07/image.png 1094w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Trong buổi hôm nay, đại diện từ Code Tốt đã chia sẻ những định hướng tối ưu web hiệu quả và có mục, đúng mục đích, đạt kết quả. Đó không chỉ là việc tối ưu PageSpeed Web, mà là tổng thể phải xác định mục tiêu dùng website vào việc gì và các bước tiến hành ra sao.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://vi.wordpress.org/files/2023/07/image-1.png\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"572\" src=\"https://vi.wordpress.org/files/2023/07/image-1-1024x572.png\" alt=\"Tìm hiểu về ReactJS, NextJS\" class=\"wp-image-1080\" srcset=\"https://vi.wordpress.org/files/2023/07/image-1-1024x572.png 1024w, https://vi.wordpress.org/files/2023/07/image-1-300x168.png 300w, https://vi.wordpress.org/files/2023/07/image-1-768x429.png 768w, https://vi.wordpress.org/files/2023/07/image-1.png 1291w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Ở phần chia sẻ của anh Hoàng từ Melisoft về mô hình NextJS sử dụng API từ bên thứ ba (như WordPress REST API), tập trung vào việc xoay quanh mô hình mô-đun hoá, tinh chỉnh liên tục, tạo ra những nền tảng có mức độ tái sử dụng cao. Anh Hoàng cũng đã giới thiệu một số kiến trúc được phát triển và tạo ra MeliPlatform khá thú vị, nhận được sự quan tâm của mọi người thông qua số câu hỏi.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Một số câu hỏi khác về WordPress cũng được giải đáp và trao đổi khá nhiệt tình.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Việc định kỳ nâng cấp website WordPress là cần thiết, đặc biệt là các phiên bản Minor (định dạng x.x.[x]). Các phiên bản Major thì cần tiến hành sao lưu trước khi nâng cấp.</li>\n\n\n\n<li>Nên sử dụng các plugin bảo mật giúp hạn chế tấn công như Wordfence.</li>\n\n\n\n<li>Việc sử dụng kết hợp giữa NextJS và WP REST API có những mục tiêu cụ thể, đặc biệt là phải quan tâm tới đối tượng sử dụng chính là ai.</li>\n\n\n\n<li>Xu hướng ChatGPT áp dụng trong công việc digital marketing.</li>\n\n\n\n<li>Việc tối ưu website phụ thuộc nhiều vào tài nguyên, chi phí, và có nhiều giải pháp khác nhau. Tuy nhiên, việc hướng tới phát triển với nguồn lực đầu tư phù hợp là hướng đi đúng đắn nhất cho doanh nghiệp.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Tham gia các sự kiện tiếp theo</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Các Meetup tiếp theo tại Hà Nội được công bố trên nhóm Zalo: <a href=\"https://zalo.me/g/gfqysr978\">https://zalo.me/g/gfqysr978</a> (nơi bạn sẽ được chọn chủ đề, thời gian, địa điểm).</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Slide chương trình:</strong><br>&#8211; <a href=\"https://docs.google.com/presentation/d/1ZNT9RDVyoBHXYN08LusDfeAKp1RCGYsm1OZBVDUZJm8/edit?fbclid=IwAR39tITgZOJHvC_j2u-Ty7I3SpIZXagPce8mIlZVxmsCKDkr9av4O73tN5I\" data-type=\"link\" data-id=\"https://docs.google.com/presentation/d/1ZNT9RDVyoBHXYN08LusDfeAKp1RCGYsm1OZBVDUZJm8/edit?fbclid=IwAR39tITgZOJHvC_j2u-Ty7I3SpIZXagPce8mIlZVxmsCKDkr9av4O73tN5I\">Tối ưu web mới nhất</a>, từ Mr. Khôi (Founder/CEO Code Tốt)<br>&#8211; Chia sẻ về <a href=\"https://www.figma.com/proto/hLFfSDh2GihHNAhPDyMA5w/Melisoft---Reactjs\">React+NextJS</a> từ Mr. Hoàng (Founder/CEO Melisoft) <br>&#8211; Quà tặng thêm 1 bài viết về <a href=\"https://codetot.vn/inp/\" data-type=\"link\" data-id=\"https://codetot.vn/inp/\">INP</a> để mọi người đọc lược qua nội dung cập nhật mới nhất.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Cảm ơn phần tài trợ nước uống từ nhà cung cấp Hosting InterData, tài trợ địa điểm của <a href=\"https://codetot.vn/ve-code-tot/\">Code Tốt</a>, sự tham gia từ các cộng đồng <strong>Yêu SEO</strong>, <strong>SEO Meetup</strong>, <strong>CxO Hà Nội</strong>, nhóm <strong><a href=\"https://www.facebook.com/groups/toiuuweb/\" data-type=\"link\" data-id=\"https://www.facebook.com/groups/toiuuweb/\">Tối ưu web ✪</a></strong> để có được những kết nối tham gia.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://vi.wordpress.org/2023/07/22/recap-wordpress-meetup-ha-noi-thang-07-2023/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"1078\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:35:\"https://vi.wordpress.org/news/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:4:\"site\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"13096074\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:11:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Fri, 11 Sep 2026 00:53:50 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:4:\"vary\";s:37:\"Accept-Encoding, accept, content-type\";s:6:\"x-olaf\";s:3:\"⛄\";s:13:\"last-modified\";s:29:\"Thu, 13 Aug 2026 14:30:35 GMT\";s:4:\"link\";s:61:\"<https://vi.wordpress.org/wp-json/>; rel=\"https://api.w.org/\"\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:4:\"gzip\";s:7:\"alt-svc\";s:5:\"clear\";s:4:\"x-nc\";s:9:\"HIT dca 2\";}s:5:\"build\";i:1788917684;s:21:\"cache_expiration_time\";i:1789131219;s:23:\"__cache_expiration_time\";i:1789131219;}', 'off');
